import { SKIP, visit } from 'unist-util-visit';
import { CLIENT_PAGE_STYLE_SCOPE, canonicalPageStyle, isPageStyleElement, pageStyleText, sanitizePageStyle, } from '../../page-style.js';
export const remarkMdxPageStyles = () => (tree) => {
    visit(tree, (node, index, parent) => {
        if (!isPageStyleElement(node) || !parent || index === undefined)
            return;
        const siblings = parent.children;
        const text = pageStyleText(node);
        const css = text === undefined ? '' : sanitizePageStyle(text, CLIENT_PAGE_STYLE_SCOPE);
        if (css) {
            siblings.splice(index, 1, canonicalPageStyle(node, css));
            return SKIP;
        }
        siblings.splice(index, 1);
        return [SKIP, index];
    });
};
